begin;
create schema domain_tax_test;
create function domain_tax_test.ok(condition boolean,message text) returns void language plpgsql as $$ begin if not coalesce(condition,false) then raise exception 'DOMAIN TAX ASSERTION FAILED: %',message; end if;raise notice 'ok - domain tax: %',message;end; $$;
create function domain_tax_test.fails(statement text,message text) returns void language plpgsql as $$ begin begin execute statement; exception when others then raise notice 'ok - domain tax: % (refused)',message;return;end;raise exception 'DOMAIN TAX ASSERTION FAILED: %',message;end; $$;
grant usage on schema domain_tax_test to anon,authenticated,service_role;
grant execute on all functions in schema domain_tax_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('ab100000-0000-0000-0000-000000000001','tax-owner@example.test'),('ab100000-0000-0000-0000-000000000002','tax-other@example.test');
insert into public.organizations(id,name,slug) values('ab200000-0000-0000-0000-000000000001','Tax tests','domain-tax-tests');
insert into public.organization_members(organization_id,user_id,role) values('ab200000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001','owner');
insert into public.websites(id,organization_id,name) values('ab300000-0000-0000-0000-000000000001','ab200000-0000-0000-0000-000000000001','Tax website');
insert into vigil.domain_launch_profiles(id,registrar_scope,stripe_account,max_registrar_minor,max_client_minor,service_fee_minor,allowed_country,terms_version,terms_url,registration_agreement_url,renewal_policy_version,retention_days,approval_reference,approved_by,valid_until)
 values('ab400000-0000-0000-0000-000000000001','namecom:live:'||repeat('a',64),'acct_fixture',2000,3000,500,'US','domain-v1','https://example.test/terms','https://www.name.com/policies/registration-agreement','manual-v1',2557,'fixture approval only','ab100000-0000-0000-0000-000000000001',now()+interval '1 day');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"ab100000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select domain_tax_test.fails('select public.domain_launch_profile()','browser cannot inspect launch profile');
select domain_tax_test.fails('select * from vigil.domain_tax_quotes','browser cannot inspect tax evidence');
select domain_tax_test.fails('select public.domain_operations_health()','customer cannot inspect operator health');
select domain_tax_test.fails('select public.domain_record_review_queue()','customer cannot inspect records queue');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select domain_tax_test.fails('select public.ensure_domain_website_policy(''ab200000-0000-0000-0000-000000000001'',''ab300000-0000-0000-0000-000000000001'',''ab100000-0000-0000-0000-000000000001'',''ab400000-0000-0000-0000-000000000001'')','discovery profile does not admit purchasing');
select domain_tax_test.fails('update vigil.domain_launch_profiles set purchasing_enabled=true','immutable release cannot be enabled by editing its flag');
select domain_tax_test.fails('insert into vigil.domain_launch_profiles(registrar_scope,stripe_account,max_registrar_minor,max_client_minor,service_fee_minor,allowed_country,terms_version,terms_url,registration_agreement_url,renewal_policy_version,retention_days,purchasing_enabled,approval_reference,approved_by,valid_until) values(''namecom:live:''||repeat(''a'',64),''acct_fixture'',2000,3000,500,''US'',''v1'',''https://example.test/terms'',''https://name.com/terms'',''manual-v1'',2557,true,''fixture approval'',''ab100000-0000-0000-0000-000000000001'',now()+interval ''1 day'')','release needs actual classification and review references');
update vigil.domain_launch_profiles set revoked_at=now();
insert into vigil.domain_launch_profiles(id,registrar_scope,stripe_account,max_registrar_minor,max_client_minor,service_fee_minor,allowed_country,terms_version,terms_url,registration_agreement_url,renewal_policy_version,retention_days,purchasing_enabled,tax_code,fee_tax_code,tax_review_reference,supplier_tax_reference,approval_reference,approved_by,valid_until)
 values('ab400000-0000-0000-0000-000000000002','namecom:live:'||repeat('a',64),'acct_fixture',2000,3000,500,'US','domain-v1','https://example.test/terms','https://www.name.com/policies/registration-agreement','manual-v1',2557,true,'txcd_20030000','txcd_20030000','fixture review only','fixture supplier review only','fixture approval only','ab100000-0000-0000-0000-000000000001',now()+interval '1 day');
select domain_tax_test.fails('select public.ensure_domain_website_policy(''ab200000-0000-0000-0000-000000000001'',''ab300000-0000-0000-0000-000000000001'',''ab100000-0000-0000-0000-000000000002'',''ab400000-0000-0000-0000-000000000002'')','other actor cannot generate a website purchasing policy');
do $$
declare p jsonb;q uuid;final_q uuid;o uuid;t uuid;
begin
 p:=public.ensure_domain_website_policy('ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000002');
 perform domain_tax_test.ok(p->>'tax_mode'='stripe','reviewed merchant release generates address-based policy');
 perform domain_tax_test.ok(p=public.ensure_domain_website_policy('ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000002'),'policy issuance is idempotent');
 q:=public.create_live_domain_quote('ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','tax-fixture.com',1200,1400,now()+interval '5 minutes');
 perform domain_tax_test.ok((select tax_status='pending' from public.domain_quotes where id=q),'preliminary quote cannot imply final tax');
 perform domain_tax_test.fails(format('select public.create_domain_purchase(%L,%L,%L,%L,%L,%L,%L,1700,''usd'',false,''domain-v1'',''manual-v1'')',q,'ab200000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001',gen_random_uuid(),gen_random_uuid(),repeat('x',100),repeat('a',64)),'preliminary quote cannot authorize checkout');
 perform domain_tax_test.fails(format('select public.create_taxed_domain_quote(%L,%L,%L,''taxcalc_wrong'',%L,100,1801,now()+interval ''1 hour'',''acct_fixture'',''[]'')',q,'ab200000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001',repeat('a',64)),'final tax total must equal approved subtotal plus tax');
 final_q:=public.create_taxed_domain_quote(q,'ab200000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001','taxcalc_fixture',repeat('a',64),100,1800,now()+interval '1 hour','acct_fixture','[]');
 perform domain_tax_test.ok(final_q=public.create_taxed_domain_quote(q,'ab200000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001','taxcalc_fixture',repeat('a',64),100,1800,now()+interval '1 hour','acct_fixture','[]'),'same calculation is not duplicated');
 perform domain_tax_test.ok(not public.claim_domain_tax_submission(final_q,'acct_fixture'),'unpaid quote cannot create reporting transaction');
 o:=public.create_domain_purchase(final_q,'ab200000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001',gen_random_uuid(),gen_random_uuid(),repeat('x',100),repeat('a',64),1800,'usd',false,'domain-v1','manual-v1');
 perform domain_tax_test.ok((select total_minor=1800 and tax_minor=100 from public.domain_quotes where id=final_q),'final tax quote persists exact consent total');
 perform domain_tax_test.fails(format('update vigil.domain_tax_quotes set tax_minor=0 where quote_id=%L',final_q),'tax evidence cannot be rewritten');
 perform domain_tax_test.fails(format('select public.record_domain_tax_result(%L,''acct_fixture'',''tax_unpaid'')',final_q),'unpaid order cannot fabricate reported sale');
 update public.domain_orders set payment_state='paid' where id=o;
 perform domain_tax_test.ok(not public.claim_domain_tax_submission(final_q,'acct_wrong'),'tax submission is account-bound');
 perform domain_tax_test.ok(public.claim_domain_tax_submission(final_q,'acct_fixture'),'paid evidence admits one idempotent reporting submission');
 perform public.record_domain_tax_result(final_q,'acct_fixture','tax_fixture');
 perform domain_tax_test.ok((select state='committed' from vigil.domain_tax_quotes where quote_id=final_q),'reported transaction has durable provider mapping');
 perform domain_tax_test.fails(format('select public.record_domain_tax_result(%L,''acct_fixture'',''tax_other'')',final_q),'submitted tax reference cannot be replaced');
 update public.domain_orders set payment_state='refunded' where id=o;
 update vigil.domain_tax_quotes set reversal_submission_at=now()-interval '24 hours' where quote_id=final_q;
 perform domain_tax_test.ok(not public.claim_domain_tax_submission(final_q,'acct_fixture',true),'uncertain reversal older than idempotency window requires review');
 perform public.record_domain_tax_result(final_q,'acct_fixture','tax_fixture',null,'tax_reconciliation_needs_review');
 perform domain_tax_test.ok((select state='review' from vigil.domain_tax_quotes where quote_id=final_q),'failure recording cannot reopen an expired submission window');
 update vigil.domain_launch_profiles set revoked_at=now() where id='ab400000-0000-0000-0000-000000000002';
 perform domain_tax_test.fails(format('select public.authorize_live_domain_action(%L,''checkout'',''namecom:live:''||repeat(''a'',64),''acct_fixture'')',o),'revoked merchant release blocks outstanding new checkout');
 perform domain_tax_test.ok((public.domain_live_policy('ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001',null,(p->>'id')::uuid,false)->>'id')=p->>'id','revocation preserves historical evidence access');
 select contact_id into t from public.domain_acceptances where quote_id=final_q;
 insert into vigil.domain_record_holds(contact_id,reason,reference,placed_by) values(t,'legal','fixture hold','ab100000-0000-0000-0000-000000000001');
 perform domain_tax_test.fails(format('delete from vigil.domain_record_holds where contact_id=%L',t),'hold history cannot be deleted');
 perform domain_tax_test.ok(public.domain_record_review_queue()='[]'::jsonb,'records younger than seven years cannot enter erasure review');
 perform domain_tax_test.ok(public.domain_operations_health()->>'activeRecordHolds'='1','operator sees active hold count');
end; $$;
reset role;
rollback;
